export const PT_MM=25.4/72;
export const clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
export const round=(v,n=2)=>Number(v.toFixed(n));
export function union(boxes){if(!boxes.length)return null;const x=Math.min(...boxes.map(b=>b.x)),y=Math.min(...boxes.map(b=>b.y));return{x,y,width:Math.max(...boxes.map(b=>b.x+b.width))-x,height:Math.max(...boxes.map(b=>b.y+b.height))-y};}
export function alignDelta(b,r,axis){switch(axis){case'left':return[r.x-b.x,0];case'right':return[r.x+r.width-b.x-b.width,0];case'cx':return[r.x+r.width/2-b.x-b.width/2,0];case'top':return[0,r.y-b.y];case'bottom':return[0,r.y+r.height-b.y-b.height];case'cy':return[0,r.y+r.height/2-b.y-b.height/2];default:return[0,0];}}
export function distribute(boxes,axis){const dim=axis==='x'?'width':'height';const ordered=boxes.map((b,i)=>({...b,index:i})).sort((a,b)=>a[axis]-b[axis]);if(ordered.length<3)return boxes.map(()=>0);const start=ordered[0][axis],last=ordered.at(-1);const gap=(last[axis]+last[dim]-start-ordered.reduce((s,b)=>s+b[dim],0))/(ordered.length-1);const result=boxes.map(()=>0);let pos=start;for(const b of ordered){result[b.index]=pos-b[axis];pos+=b[dim]+gap;}return result;}
export function snapBox(b,xTargets,yTargets,tolerance){const find=(values,targets)=>{let best=null;for(const v of values)for(const t of targets){const d=t-v;if(Math.abs(d)<=tolerance&&(!best||Math.abs(d)<Math.abs(best.delta)))best={delta:d,target:t};}return best;};return{x:find([b.x,b.x+b.width/2,b.x+b.width],xTargets),y:find([b.y,b.y+b.height/2,b.y+b.height],yTargets)};}
export function parsePath(d){const ts=(d||'').match(/[a-zA-Z]|[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:[eE][-+]?\d+)?/g)||[];const sizes={M:2,L:2,H:1,V:1,C:6,S:4,Q:4,T:2,A:7,Z:0};let i=0,c='',x=0,y=0,sx=0,sy=0,prev=null;const out=[];while(i<ts.length){if(/[a-z]/i.test(ts[i]))c=ts[i++];let u=c.toUpperCase(),n=sizes[u];if(n===undefined)throw Error('Неподдерживаемый контур');if(u==='Z'){out.push({type:'Z',v:[]});x=sx;y=sy;c='';prev=null;continue;}if(i+n>ts.length||!c)throw Error('Некорректный контур');let v=ts.slice(i,i+n).map(Number);if(v.some(z=>!Number.isFinite(z)))throw Error('Некорректные координаты');i+=n;const rel=c!==u;if(u==='H'){v=[(rel?x:0)+v[0],y];u='L';}else if(u==='V'){v=[x,(rel?y:0)+v[0]];u='L';}else if(u==='A'){if(rel){v[5]+=x;v[6]+=y;}}else{if(rel)for(let k=0;k<v.length;k+=2){v[k]+=x;v[k+1]+=y;}if(u==='S'){const p=prev?.type==='C'?prev.v.slice(2,4):[x,y];v=[2*x-p[0],2*y-p[1],...v];u='C';}if(u==='T'){const p=prev?.type==='Q'?prev.v.slice(0,2):[x,y];v=[2*x-p[0],2*y-p[1],...v];u='Q';}}const cmd={type:u,v};out.push(cmd);x=v.at(-2);y=v.at(-1);if(u==='M'){sx=x;sy=y;c=rel?'l':'L';}prev=cmd;}return out;}
export const pathString=cs=>cs.map(c=>c.type+c.v.map(v=>round(v,5)).join(' ')).join(' ');
export function splitSegment(cs,index){if(index<=0||!cs[index]||!['L','C','Q'].includes(cs[index].type))return false;const p=cs[index-1].v.slice(-2),c=cs[index],v=c.v,mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];if(c.type==='L'){cs.splice(index,0,{type:'L',v:mid(p,v)});}else if(c.type==='C'){const a=mid(p,v.slice(0,2)),b=mid(v.slice(0,2),v.slice(2,4)),cc=mid(v.slice(2,4),v.slice(4,6)),d=mid(a,b),e=mid(b,cc),f=mid(d,e);cs.splice(index,1,{type:'C',v:[...a,...d,...f]},{type:'C',v:[...e,...cc,...v.slice(4,6)]});}else{const a=mid(p,v.slice(0,2)),b=mid(v.slice(0,2),v.slice(2,4)),f=mid(a,b);cs.splice(index,1,{type:'Q',v:[...a,...f]},{type:'Q',v:[...b,...v.slice(2,4)]});}return true;}
